import statistics


def annualised_vol(returns):
    # sample standard deviation of daily returns, scaled to 252 trading days
    return statistics.stdev(returns) * math.sqrt(252)


def test_two_days():
    # daily returns of +1% and -1%
    # mean 0, squared gaps 0.0001 + 0.0001 = 0.0002, over n - 1 = 1
    vol = annualised_vol([0.01, -0.01])
    assert vol == pytest.approx(math.sqrt(0.0002 * 252))


def test_constant_returns():
    # the same return every day, such as 0.3%
    vol = annualised_vol([0.003, 0.003, 0.003])
    assert vol == pytest.approx(0.0)
